package main

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"net/http"
	"sync"
	"time"

	"golang.org/x/crypto/bcrypt"
)

// RateLimiter implements a token bucket algorithm for API protection
type RateLimiter struct {
	tokens     int32
	maxTokens  int32
	refillRate int32
	lastRefill time.Time
	mu         sync.Mutex
}

func NewRateLimiter(max, refillRate int32) *RateLimiter {
	return &RateLimiter{
		tokens:     max,
		maxTokens:  max,
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// refill adds tokens based on elapsed time (must be called with lock held)
func (rl *RateLimiter) refill() {
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill)
	newTokens := int32(elapsed/time.Second) * rl.refillRate
	if newTokens > 0 {
		rl.tokens += newTokens
		if rl.tokens > rl.maxTokens {
			rl.tokens = rl.maxTokens
		}
		rl.lastRefill = now
	}
}

// consume attempts to consume one token, returns true if allowed
func (rl *RateLimiter) consume() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refill()
	if rl.tokens <= 0 {
		return false
	}
	rl.tokens--
	return true
}

// Per-IP rate limiters
var (
	limiters   = make(map[string]*RateLimiter)
	limitersMu sync.Mutex
)

func getLimiter(ip string) *RateLimiter {
	limitersMu.Lock()
	defer limitersMu.Unlock()
	rl, exists := limiters[ip]
	if !exists {
		// Allow 5 requests per second for password reset
		rl = NewRateLimiter(5, 5)
		limiters[ip] = rl
	}
	return rl
}

// User store
type User struct {
	Email        string
	PasswordHash []byte
	ResetToken   string
	ResetExpiry  time.Time
}

var (
	users   = make(map[string]*User)
	usersMu sync.RWMutex
)

func generateToken() (string, error) {
	b := make([]byte, 32)
	_, err := rand.Read(b)
	if err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// handlePasswordResetRequest initiates a password reset
func handlePasswordResetRequest(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ip := r.RemoteAddr
	rl := getLimiter(ip)
	if !rl.consume() {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	email := r.FormValue("email")
	if email == "" {
		http.Error(w, "Email required", http.StatusBadRequest)
		return
	}

	usersMu.RLock()
	user, exists := users[email]
	usersMu.RUnlock()

	// Always return success to prevent email enumeration
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "If the email exists, a reset link has been sent.")

	if !exists {
		return
	}

	token, err := generateToken()
	if err != nil {
		return
	}

	usersMu.Lock()
	user.ResetToken = token
	user.ResetExpiry = time.Now().Add(15 * time.Minute)
	usersMu.Unlock()

	// In production, send email with token
	_ = token
}

// handlePasswordReset completes the password reset
func handlePasswordReset(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ip := r.RemoteAddr
	rl := getLimiter(ip)
	if !rl.consume() {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	token := r.FormValue("token")
	newPassword := r.FormValue("password")

	if token == "" || newPassword == "" {
		http.Error(w, "Token and password required", http.StatusBadRequest)
		return
	}

	if len(newPassword) < 8 {
		http.Error(w, "Password must be at least 8 characters", http.StatusBadRequest)
		return
	}

	usersMu.RLock()
	var targetUser *User
	for _, u := range users {
		// Constant-time comparison to prevent timing attacks on the reset token
		if u.ResetToken != "" && subtle.ConstantTimeCompare([]byte(u.ResetToken), []byte(token)) == 1 {
			if time.Now().Before(u.ResetExpiry) {
				targetUser = u
			}
			break
		}
	}
	usersMu.RUnlock()

	if targetUser == nil {
		http.Error(w, "Invalid or expired token", http.StatusBadRequest)
		return
	}

	hash, err := bcrypt.GenerateFromPassword([]byte(newPassword), bcrypt.DefaultCost)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	usersMu.Lock()
	targetUser.PasswordHash = hash
	targetUser.ResetToken = ""
	targetUser.ResetExpiry = time.Time{}
	usersMu.Unlock()

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Password reset successful")
}

func main() {
	// Seed a test user
	hash, _ := bcrypt.GenerateFromPassword([]byte("testpassword123"), bcrypt.DefaultCost)
	users["admin@example.com"] = &User{
		Email:        "admin@example.com",
		PasswordHash: hash,
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/reset-request", handlePasswordResetRequest)
	mux.HandleFunc("/reset", handlePasswordReset)

	// Configure timeouts to mitigate slow-client (Slowloris) DoS attacks
	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadTimeout:       10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	srv.ListenAndServe()
}
